files.content:
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
  background: #1e1e2f;
  color: #f0f0f0;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 100vh;
  padding: 20px;
}

.card {
  background: #2a2a40;
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 800px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.5);
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 8px;
  color: #ffffff;
}

.subtitle {
  font-size: 1rem;
  color: #b0b0c8;
  margin-bottom: 32px;
}

.palette {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 16px;
  margin-bottom: 32px;
}

.swatch {
  flex: 1 1 120px;
  min-width: 100px;
  max-width: 140px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
}

.color-box {
  width: 100%;
  aspect-ratio: 1 / 1;
  border-radius: 16px;
  background-color: #ccc;
  box-shadow: inset 0 0 0 2px rgba(255, 255, 255, 0.15);
  transition: box-shadow 0.2s ease, transform 0.1s ease;
}

.color-box.locked {
  box-shadow: inset 0 0 0 3px #ffd966, 0 0 0 3px #ffd966;
}

.hex-code {
  font-family: 'Courier New', monospace;
  font-size: 1rem;
  font-weight: 600;
  letter-spacing: 0.05em;
  color: #e0e0f0;
  background: #1e1e2f;
  padding: 4px 10px;
  border-radius: 8px;
  user-select: all;
}

.lock-btn {
  background: #3a3a55;
  border: 2px solid transparent;
  border-radius: 8px;
  padding: 6px 12px;
  font-size: 0.9rem;
  font-weight: 600;
  color: #d0d0e8;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s, transform 0.1s;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 36px;
}

.lock-btn:hover {
  background: #4a4a6a;
  color: #ffffff;
}

.lock-btn:focus-visible {
  outline: 3px solid #7aa2f7;
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.96);
}

.lock-btn[aria-pressed="true"] {
  background: #ffd966;
  color: #1e1e2f;
  border-color: #ffd966;
}

.lock-btn[aria-pressed="true"]:hover {
  background: #ffe68c;
}

.generate-btn {
  background: #7aa2f7;
  border: none;
  border-radius: 12px;
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 700;
  color: #1e1e2f;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
  box-shadow: 0 4px 12px rgba(122, 162, 247, 0.3);
  min-height: 48px;
}

.generate-btn:hover {
  background: #9bb8ff;
  box-shadow: 0 6px 16px rgba(122, 162, 247, 0.4);
}

.generate-btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 3px;
}

.generate-btn:active {
  transform: scale(0.97);
  box-shadow: 0 2px 8px rgba(122, 162, 247, 0.3);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }

  h1 {
    font-size: 1.6rem;
  }

  .palette {
    gap: 12px;
  }

  .swatch {
    flex: 1 1 80px;
    min-width: 70px;
  }

  .hex-code {
    font-size: 0.85rem;
    padding: 3px 6px;
  }

  .lock-btn {
    font-size: 0.8rem;
    padding: 4px 8px;
    min-height: 32px;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  const SWATCH_COUNT = 5;
  let locked = new Array(SWATCH_COUNT).fill(false);
  let colors = [];

  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
  }

  function generatePalette() {
    const baseHue = Math.floor(Math.random() * 360);
    const scheme = Math.random() < 0.5 ? 'analogous' : 'triadic';
    const newColors = [];

    for (let i = 0; i < SWATCH_COUNT; i++) {
      if (locked[i] && colors[i]) {
        newColors.push(colors[i]);
        continue;
      }

      let hue;
      if (scheme === 'analogous') {
        hue = (baseHue + i * 30 + (Math.random() * 10 - 5)) % 360;
      } else {
        hue = (baseHue + i * 120 + (Math.random() * 10 - 5)) % 360;
      }
      if (hue < 0) hue += 360;

      const sat = 50 + Math.floor(Math.random() * 40);
      const light = 45 + Math.floor(Math.random() * 25);
      newColors.push(hslToHex(hue, sat, light));
    }

    colors = newColors;
    render();
  }

  function render() {
    paletteEl.innerHTML = '';

    for (let i = 0; i < SWATCH_COUNT; i++) {
      const swatch = document.createElement('div');
      swatch.className = 'swatch';

      const colorBox = document.createElement('div');
      colorBox.className = 'color-box' + (locked[i] ? ' locked' : '');
      colorBox.style.backgroundColor = colors[i];
      colorBox.setAttribute('aria-label', `Color swatch ${i + 1}: ${colors[i]}`);
      colorBox.setAttribute('role', 'img');

      const hexCode = document.createElement('span');
      hexCode.className = 'hex-code';
      hexCode.textContent = colors[i];

      const lockBtn = document.createElement('button');
      lockBtn.type = 'button';
      lockBtn.className = 'lock-btn';
      lockBtn.setAttribute('aria-pressed', String(locked[i]));
      lockBtn.setAttribute('aria-label', locked[i] ? `Unlock color ${colors[i]}` : `Lock color ${colors[i]}`);
      lockBtn.textContent = locked[i] ? '🔒 Locked' : '🔓 Lock';

      lockBtn.addEventListener('click', () => {
        locked[i] = !locked[i];
        render();
      });

      swatch.appendChild(colorBox);
      swatch.appendChild(hexCode);
      swatch.appendChild(lockBtn);
      paletteEl.appendChild(swatch);
    }
  }

  generateBtn.addEventListener('click', generatePalette);

  // Initial palette
  generatePalette();
})();
